import{_ as r,a as t}from"./chunks/compare-tempsweep.B68yRgr8.js";import{_ as s,o as a,c as o,ai as l}from"./chunks/framework.C33Uq6m-.js";const h=JSON.parse('{"title":"Comparer","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/compare.md","filePath":"fr/guide/compare.md"}'),i={name:"fr/guide/compare.md"};function n(u,e,d,p,m,c){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="comparer" tabindex="-1">Comparer <a class="header-anchor" href="#comparer" aria-label="Permalink to &quot;Comparer&quot;">​</a></h1><p>La page Comparer vous permet d&#39;exécuter le même prompt à travers plusieurs modèles ou configurations simultanément et de comparer les résultats côté à côté.</p><p><strong>Élément de la barre latérale :</strong> Comparer <strong>Route :</strong> <code>/compare</code></p><p><img src="'+r+'" alt="Comparaison côté à côté"></p><h2 id="vue-d-ensemble-de-l-interface" tabindex="-1">Vue d&#39;ensemble de l&#39;interface <a class="header-anchor" href="#vue-d-ensemble-de-l-interface" aria-label="Permalink to &quot;Vue d&#39;ensemble de l&#39;interface&quot;">​</a></h2><p>La page comporte une zone de saisie de prompt en haut et une grille configurable de <strong>slots</strong> en dessous. Chaque slot représente une combinaison modèle/paramètres.</p><h2 id="configurer-les-slots" tabindex="-1">Configurer les slots <a class="header-anchor" href="#configurer-les-slots" aria-label="Permalink to &quot;Configurer les slots&quot;">​</a></h2><ol><li>Cliquez sur <strong>Ajouter un slot</strong> pour créer un slot de comparaison (jusqu&#39;à 4 slots).</li><li>Pour chaque slot, configurez : <ul><li><strong>Modèle</strong> -- Sélectionnez parmi vos modèles Ollama installés (les modèles d&#39;embedding sont filtrés)</li><li><strong>Température</strong> -- Contrôle l&#39;aléatoire (0 = déterministe, plus élevé = plus créatif)</li><li><strong>Prompt système</strong> -- Instructions optionnelles au niveau système</li><li><strong>Paramètres d&#39;échantillonnage</strong> -- Top-k, top-p, seed et autres options Ollama</li></ul></li></ol><p>Chaque slot affiche ses paramètres sous forme de pastilles pour une référence rapide.</p><h2 id="lancer-une-comparaison" tabindex="-1">Lancer une comparaison <a class="header-anchor" href="#lancer-une-comparaison" aria-label="Permalink to &quot;Lancer une comparaison&quot;">​</a></h2><ol><li>Saisissez votre prompt dans la zone de saisie partagée.</li><li>Cliquez sur <strong>Lancer tout</strong>. Tous les slots diffusent leurs réponses simultanément.</li><li>Observez les résultats apparaître côté à côté en temps réel.</li></ol><h2 id="vues" tabindex="-1">Vues <a class="header-anchor" href="#vues" aria-label="Permalink to &quot;Vues&quot;">​</a></h2><h3 id="vue-grille" tabindex="-1">Vue grille <a class="header-anchor" href="#vue-grille" aria-label="Permalink to &quot;Vue grille&quot;">​</a></h3><p>La vue par défaut. Tous les slots affichent leurs résultats en streaming dans une disposition en grille. Chaque slot montre :</p><ul><li>La réponse du modèle</li><li>Une pastille de paramètres indiquant le nom du modèle et la température</li></ul><h3 id="vue-diff" tabindex="-1">Vue diff <a class="header-anchor" href="#vue-diff" aria-label="Permalink to &quot;Vue diff&quot;">​</a></h3><p>Passez en vue diff pour voir le <strong>surlignage mot par mot</strong> des différences entre deux sorties. Le texte ajouté est surligné en vert, le texte supprimé en rouge.</p><p><img src="'+t+'" alt="Balayage de température"></p><h2 id="barre-de-metriques" tabindex="-1">Barre de métriques <a class="header-anchor" href="#barre-de-metriques" aria-label="Permalink to &quot;Barre de métriques&quot;">​</a></h2><p>Sous la grille, une <strong>barre de métriques</strong> visuelle compare les indicateurs clés de performance entre tous les slots :</p><table tabindex="0"><thead><tr><th>Métrique</th><th>Description</th></tr></thead><tbody><tr><td><strong>TTFT</strong></td><td>Time to first token -- rapidité de début de réponse de chaque modèle</td></tr><tr><td><strong>Tokens/sec</strong></td><td>Débit de génération</td></tr><tr><td><strong>Total tokens</strong></td><td>Nombre de tokens de completion</td></tr></tbody></table><h2 id="presets-rapides" tabindex="-1">Presets rapides <a class="header-anchor" href="#presets-rapides" aria-label="Permalink to &quot;Presets rapides&quot;">​</a></h2><p>Des presets en un clic pour configurer des scénarios de comparaison courants :</p><ul><li><strong>Balayage de température</strong> -- Même modèle à 3 températures différentes (0.2, 0.7, 1.2) pour observer l&#39;évolution de la créativité</li><li><strong>Paire déterministe</strong> -- Même modèle, même seed, mêmes paramètres -- vérifie la reproductibilité</li></ul><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Même modèle, paramètres différents</strong> est souvent plus instructif que comparer des modèles différents. Essayez de varier la température ou les prompts système.</li><li><strong>Les slots persistent</strong> lors de la navigation entre les pages durant la session.</li><li>Utilisez un prompt à <strong>faible nombre de tokens</strong> pour des itérations rapides.</li></ul>',26)])])}const b=s(i,[["render",n]]);export{h as __pageData,b as default};
